import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

// ── Animated Counter ──────────────────────────────────────────────────────────
function Counter({ target, suffix = '' }) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    let start = 0;
    const step = Math.ceil(target / 60);
    const t = setInterval(() => {
      start += step;
      if (start >= target) { setVal(target); clearInterval(t); }
      else setVal(start);
    }, 20);
    return () => clearInterval(t);
  }, [target]);
  return <>{val.toLocaleString()}{suffix}</>;
}

// ── World Map SVG ─────────────────────────────────────────────────────────────
function WorldMapSVG() {
  const ports = [
    { name: 'Singapore', x: 71.2, y: 51.5, status: 'open' },
    { name: 'Shanghai', x: 78, y: 35, status: 'open' },
    { name: 'Rotterdam', x: 47.2, y: 26, status: 'open' },
    { name: 'Los Angeles', x: 12, y: 38, status: 'open' },
    { name: 'Dubai', x: 60, y: 40, status: 'risk' },
    { name: 'Hamburg', x: 48.5, y: 22, status: 'open' },
    { name: 'Yokohama', x: 80, y: 32, status: 'open' },
    { name: 'Busan', x: 78.5, y: 33, status: 'open' },
    { name: 'Mumbai', x: 63, y: 45, status: 'open' },
    { name: 'Lagos', x: 46.5, y: 50, status: 'open' },
  ];
  const routes = [
    { x1: 71.2, y1: 51.5, x2: 47.2, y2: 26 },
    { x1: 78, y1: 35, x2: 71.2, y2: 51.5 },
    { x1: 47.2, y1: 26, x2: 12, y2: 38 },
