  ];
  return (
    <div className="world-map-wrapper" style={{ height: 480 }}>
      <svg viewBox="0 0 100 60" style={{ width: '100%', height: '100%' }}>
        <defs>
          <radialGradient id="portGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#00c9a7" stopOpacity="0.8" />
            <stop offset="100%" stopColor="#00c9a7" stopOpacity="0" />
          </radialGradient>
        </defs>
        {/* Ocean */}
        <rect width="100" height="60" fill="#030d1a" />
        {/* Grid */}
        {[...Array(11)].map((_, i) => <line key={`v${i}`} x1={i * 10} y1="0" x2={i * 10} y2="60" stroke="rgba(30,58,95,0.3)" strokeWidth="0.1" />)}
        {[...Array(7)].map((_, i) => <line key={`h${i}`} x1="0" y1={i * 10} x2="100" y2={i * 10} stroke="rgba(30,58,95,0.3)" strokeWidth="0.1" />)}
