        <g opacity="0.18" fill="#1e4a7a">
          <path d="M 8 18 L 22 16 L 26 26 L 22 42 L 16 44 L 8 36 Z" />
          <path d="M 16 42 L 24 40 L 28 56 L 20 58 L 14 54 Z" />
          <path d="M 42 14 L 56 12 L 60 24 L 52 30 L 40 28 Z" />
          <path d="M 44 30 L 58 28 L 62 50 L 52 56 L 42 52 Z" />
          <path d="M 56 12 L 86 10 L 90 32 L 76 40 L 58 36 Z" />
          <path d="M 78 42 L 96 40 L 98 56 L 84 58 L 76 52 Z" />
          <path d="M 0 12 L 8 10 L 10 26 L 4 28 L 0 22 Z" />
        </g>
        {/* Routes */}
        {routes.map((r, i) => (
          <g key={i}>
            <line x1={r.x1} y1={r.y1} x2={r.x2} y2={r.y2} stroke="rgba(0,149,232,0.3)" strokeWidth="0.2" strokeDasharray="0.8 0.5" />
